                const formattedLogin = formatLoginPrivateDomain(detail.displayName ?? '', login);

                suggestions.push({
                    text: formattedLogin,
                    alternateText: login,
                    icons: [
                        {
                            source: detail.avatar,
                            name: login,
                            type: Icon.ICON_TYPE_AVATAR,
                        },
                    ],
                });
            });

            return suggestions;
        },
        [currentUserPersonalDetails, formatLoginPrivateDomain, weightedPersonalDetails],
    );

