const getMentionOptions = useCallback(
        (mentionFilter: string): Mention[] => {
            const suggestions: Mention[] = [];

            if (CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT.includes(mentionFilter)) {
                suggestions.push({
                    text: CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT,
                    alternateText: CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT,
                    icons: [
                        {
                            source: Expensicons.Megaphone,
                            type: Icon.ICON_TYPE_SVG,
                        },
                    ],
                });
            }

            const currentUserLogin = currentUserPersonalDetails.login ?? '';
            const currentUserAccountID = currentUserPersonalDetails.accountID;
            const formattedCurrentUserLogin = OptionsListUtils.getDisplayNameForParticipant(currentUserAccountID, false, false);
            const currentUserFiltered = formatLoginPrivateDomain(formattedCurrentUserLogin, currentUserLogin);
            if (currentUserFiltered.toLowerCase().includes(mentionFilter.toLowerCase())) {
                suggestions.push({
                    text: currentUserFiltered,
                    alternateText: currentUserLogin.toLowerCase(),
                    icons: [
                        {
                            source: currentUserPersonalDetails.avatar,
                            name: currentUserLogin,
                            type: Icon.ICON_TYPE_AVATAR,
                        },
                    ],
                });
            }

            const filteredPersonalDetails = Object.values(weightedPersonalDetails).filter((detail) => {
                if (!detail) {
                    return false;
                }
                const login = detail.login ?? '';
                const displayName = detail.displayName ?? '';

                // If the user is already added, don't add them again.
                if (currentUserLogin === login) {
                    return false;
                }

                // We want to match user's login and displayName
                if (!login.toLowerCase().includes(mentionFilter.toLowerCase()) && !displayName.toLowerCase().includes(mentionFilter.toLowerCase())) {
                    return false;
                }

                return true;
            });

            const sortedPersonalDetails = lodashSortBy(filteredPersonalDetails, compareUserInList);
            sortedPersonalDetails.slice(0, 5).forEach((detail) => {
                if (!detail) {
                    return;
                }
                const login = detail.login ?? '';
                const formattedLogin = formatLoginPrivateDomain(detail.displayName ?? '', login);

                suggestions.push({
                    text: formattedLogin,
                    alternateText: login,
                    icons: [
                        {
                            source: detail.avatar,
                            name: login,
                            type: Icon.ICON_TYPE_AVATAR,
                        },
                    ],
                });
            });

            return suggestions;
        },
        [currentUserPersonalDetails, formatLoginPrivateDomain, weightedPersonalDetails],
    );

